import numpy as np
from scipy.ndimage import distance_transform_edt,label,gaussian_filter1d
from scipy.spatial import cKDTree
from PIL import Image,ImageDraw

def boundary(m):
 # Directed pixel-square boundaries, interior on right.
 y,x=np.where(m)
 edges={}
 for yy,xx in zip(y.tolist(),x.tolist()):
  if yy==0 or not m[yy-1,xx]:edges.setdefault((xx,yy),[]).append((xx+1,yy))
  if xx==m.shape[1]-1 or not m[yy,xx+1]:edges.setdefault((xx+1,yy),[]).append((xx+1,yy+1))
  if yy==m.shape[0]-1 or not m[yy+1,xx]:edges.setdefault((xx+1,yy+1),[]).append((xx,yy+1))
  if xx==0 or not m[yy,xx-1]:edges.setdefault((xx,yy+1),[]).append((xx,yy))
 loops=[]
 while edges:
  start=next(iter(edges));p=start;pts=[]
  while True:
   pts.append(p);dest=edges[p].pop()
   if not edges[p]:del edges[p]
   p=dest
   if p==start:break
   if p not in edges:break
  if len(pts)>8:loops.append(np.array(pts,float)-.5)
 return loops

def resample(p,spacing=1):
 p=np.asarray(p);d=np.r_[0,np.cumsum(np.linalg.norm(np.diff(p,axis=0),axis=1))]
 t=np.linspace(0,d[-1],max(2,int(np.ceil(d[-1]/spacing))+1))
 return np.c_[np.interp(t,d,p[:,0]),np.interp(t,d,p[:,1])]

def make_loops(mask,inset=4,spacing=3):
 d=distance_transform_edt(mask);loops=[]
 for lev in np.arange(inset,d.max()-.5,spacing):
  for p in boundary(d>=lev):
   p=gaussian_filter1d(p,1.5,axis=0,mode='wrap')
   p=resample(np.r_[p,p[:1]],1.2)[:-1]
   loops.append(p)
 return loops

def plan(mask,inset=4,spacing=3):
 loops=make_loops(mask,inset,spacing)
 # Minimum spanning tree among nested contour loops; connectors remain locally within ink.
 n=len(loops);trees=[cKDTree(p) for p in loops];edges=[]
 for i in range(n):
  for j in range(i):
   ds,ix=trees[j].query(loops[i]);a=ds.argmin();edges.append((ds[a],i,j,a,int(ix[a])))
 parent=list(range(n))
 def root(i):
  while parent[i]!=i:i=parent[i]
  return i
 adj=[[] for _ in loops]
 for dist,i,j,a,b in sorted(edges):
  ri,rj=root(i),root(j)
  if ri!=rj:
   parent[ri]=rj;adj[i].append((j,a,b));adj[j].append((i,b,a))
 # Start deepest contour, away from edges for initial loading footprint.
 start=n-1;path=[]
 def visit(i,from_i,entry):
  p=loops[i];children={}
  for j,a,b in adj[i]:
   if j!=from_i:children.setdefault(a,[]).append((j,b))
  for k in range(len(p)+1):
   a=(entry+k)%len(p);path.append(p[a])
   if k<len(p):
    for j,b in children.get(a,[]):
     path.extend(resample([p[a],loops[j][b]],1.2)[1:]);visit(j,i,b)
     path.extend(resample([loops[j][b],p[a]],1.2)[1:])
 visit(start,-1,0)
 return np.asarray(path),loops

if __name__=='__main__':
 m=np.array(Image.open('/app/target.png')).mean(2)<100;l,n=label(m)
 for c in range(1,n+1):
  path,loops=plan(l==c);print(c,'loops',len(loops),'points',len(path),'length mm',np.linalg.norm(np.diff(path,axis=0),axis=1).sum()*.22186)
