"""Fill small camera-observed enclosed gaps, joining gaps through safe ink interiors."""
from gen import *
from contours import resample
from PIL import Image
from scipy.ndimage import label,distance_transform_edt,map_coordinates
import heapq,math
m=np.array(Image.open('/app/target.png')).mean(2)<100;labels,n=label(m);dist=distance_transform_edt(m)
holes=json.loads((ROOT/'holes.json').read_text())
groups={}
for h in holes:
 u,v=np.rint(h['center']).astype(int);c=int(labels[v,u]);groups.setdefault(c,[]).append(h)

def inside_path(a,b,clearance=4.5):
 pts=resample([a,b],.7)
 return np.min(map_coordinates(dist,[pts[:,1],pts[:,0]],order=1))>=clearance

def route(a,b):
 if inside_path(a,b):return resample([a,b],1.2)
 start=tuple(np.rint(a).astype(int));goal=tuple(np.rint(b).astype(int));q=[(0,start)];cost={start:0};parents={};moves=[(dx,dy,math.hypot(dx,dy)) for dx in [-1,0,1] for dy in [-1,0,1] if dx or dy]
 while q:
  _,p=heapq.heappop(q)
  if p==goal:break
  for dx,dy,w in moves:
   nx,ny=p[0]+dx,p[1]+dy
   if not(0<=nx<1024 and 0<=ny<1024) or dist[ny,nx]<5:continue
   v=(nx,ny);nc=cost[p]+w*(1+.3/max(dist[ny,nx],1))
   if nc<cost.get(v,1e30):cost[v]=nc;parents[v]=p;heapq.heappush(q,(nc+math.hypot(nx-goal[0],ny-goal[1]),v))
 else:raise RuntimeError('No safe interior connector')
 path=[goal]
 while path[-1]!=start:path.append(parents[path[-1]])
 path=np.array(path[::-1],float)
 # Smooth staircase corners while staying safely inside the ink.
 from scipy.ndimage import gaussian_filter1d
 smooth=gaussian_filter1d(path,2,axis=0);smooth[0]=a;smooth[-1]=b
 return resample(smooth,1.2)

planned={}
for c,hs in groups.items():
 path=[]
 for h in hs:
  x0,y0,x1,y1=h['bounds'];local=[]
  # Draw along rows of the enclosed gap; all connectors remain inside exemplar ink.
  for k,y in enumerate(np.arange(y0,y1+.8,1.5)):
   a=[x0,y];b=[x1,y]
   if k%2:a,b=b,a
   if not inside_path(a,b):continue
   if local:local.extend(route(local[-1],a)[1:])
   else:local.append(a)
   local.extend(resample([a,b],.9)[1:])
  if not local:continue
  if path:path.extend(route(path[-1],local[0])[1:])
  path.extend(local)
 if path:planned[c]=np.asarray(path)
print('Touch-up groups and rows',[(c,len(p)) for c,p in planned.items()],flush=True)
np.savez(ROOT/'touchup_paths.npz',**{str(c):p for c,p in planned.items()})
if '--execute' not in sys.argv:sys.exit()
for c,p in planned.items():
 world=np.array([uv(u,v,SURFACE-.001) for u,v in p])
 dip();goto([*world[0,:2],.04],name='touchup_hover');goto(world[0],speed=.008,name=f'touchup_{c}_press')
 for i in range(0,len(world),180):send(world[i:i+180],name=f'touchup_{c}_fill',cams=[])
 goto([*world[-1,:2],.045],speed=.018,name=f'touchup_{c}_lift')
goto([-.3,0,.13],name='final_clear')
o=obs(name='final');Image.fromarray(o.last['canvas_cam']).save(ROOT/'main_final.png')
(ROOT/'final_status.json').write_text(json.dumps(r.status(),indent=2))
(ROOT/'contact_count.txt').write_text(str(5+len(planned)))
